#include <iostream>
#include <iomanip>
#include <cstdio>

int main() {
    double val = 1234567.89;
    double small = 0.0000875;
    double whole = 8750000.0;

    // Fixed-point and scientific format using printf
    std::printf("Fixed: %f\n", val);
    std::printf("Lower g: %g\n", val);
    std::printf("Upper G: %G\n", val);
    std::printf("Small g: %g\n", small);
    std::printf("Whole g: %g\n", whole);

    // Equivalent modern C++17 stream formatting
    std::cout << "C++ fixed: " << std::fixed << val << '\n';
    std::cout << "C++ defaultfloat: " << std::defaultfloat << val << '\n';
    return 0;
}

#include <iostream>
#include <iomanip>
#include <cstdio>

int main() {
    char letter = 'A';
    const char text[] = "C++17";

    // Using %c, %s, %p and %%
    std::printf("Char: %c\n", letter);
    std::printf("String: %s\n", text);
    std::printf("Progress: 100%% complete\n");

    // Field widths for integers right-justification
    std::printf("Field width 4 right-justified:\n");
    std::printf("%4d\n", 1);
    std::printf("%4d\n", 12);
    std::printf("%4d\n", 12345);

    // C++17 stream formatting equivalent for field width
    std::cout << "C++ setw(4):\n";
    std::cout << std::setw(4) << 1 << '\n';
    std::cout << std::setw(4) << 12 << '\n';
    std::cout << std::setw(4) << 12345 << '\n';

    return 0;
}
